// Donations installer: Donate page + donation detail page, one cart with a Seva section and a Donation section.
// Run from the repo root or apps\web:  node install-donations.mjs
// Old copies are saved as <name>.bak. en.json / ta.json get a new "donate" block and new "shop" keys; nothing is removed.
// Requires install-seva-shop.mjs, install-seva-ui.mjs and install-seva-ui-v2.mjs to have been run first.
import fs from 'node:fs';
import path from 'node:path';
let root = process.argv[2] ? path.resolve(process.argv[2]) : process.cwd();
const isWeb = (d) => fs.existsSync(path.join(d, 'src', 'dictionaries', 'en.json'));
if (!isWeb(root) && isWeb(path.join(root, 'apps', 'web'))) root = path.join(root, 'apps', 'web');
if (!isWeb(root)) { console.error('Run this from the repo root or apps\\web.'); process.exit(1); }
if (!fs.existsSync(path.join(root, 'src', 'components', 'sevas', 'SankalpamWizard.tsx'))) { console.error('Run install-seva-ui.mjs first (SankalpamWizard.tsx missing).'); process.exit(1); }
console.log('Installing into ' + root + '\n');
const FILES = {"src/data/donations.ts":"// DUMMY DATA. The CMS portal will replace this file: keep the shape, swap the source.\n// The 5 donation items come from the old site's Donation page. The two Corpus Fund items are placeholders.\n// `amount: 0` means \"as per the donor's wish\".\n\nimport type { L } from './sevas';\n\nexport type DonationKind = 'donation' | 'corpus';\n\nexport type Donation = {\n  slug: string;\n  kind: DonationKind;\n  name: L;\n  amount: number;          // fixed amount in rupees; 0 = donor chooses\n  minAmount: number;       // lowest amount a donor may choose (only when amount is 0)\n  maxQty: number;\n  status: 'open' | 'closed';\n  description: { en: string[]; ta: string[] }; // paragraphs; empty until the ashram writes them\n};\n\nconst base = { minAmount: 1, maxQty: 10, status: 'open' as const, description: { en: [], ta: [] } };\n\nexport const DONATIONS: Donation[] = [\n  { ...base, slug: 'gurukanikkai', kind: 'donation', amount: 0,\n    name: { en: 'Gurukanikkai', ta: 'குருகாணிக்கை' } },\n  { ...base, slug: 'general-donation', kind: 'donation', amount: 0,\n    name: { en: 'General Donation', ta: 'பொது நன்கொடை' } },\n  { ...base, slug: 'veda-samrakshanam', kind: 'donation', amount: 3000,\n    name: { en: 'Veda Samrakshanam', ta: 'வேத ஸம்ரக்ஷணம்' } },\n  { ...base, slug: 'go-samrakshanam', kind: 'donation', amount: 3000,\n    name: { en: 'Go Samrakshanam (One month for a cow)', ta: 'கோ ஸம்ரக்ஷணம் (ஒரு பசுவிற்கு ஒரு மாதம்)' } },\n  { ...base, slug: 'vriksha-samrakshanam', kind: 'donation', amount: 2000,\n    name: { en: 'Vriksha Samrakshanam', ta: 'விருக்ஷ சம்ரக்ஷணம்' } },\n\n  // PLACEHOLDERS: replace with the real Corpus Fund items\n  { ...base, slug: 'donation-corpus-fund', kind: 'corpus', amount: 0,\n    name: { en: 'Corpus Fund', ta: 'கார்பஸ் நிதி' } },\n  { ...base, slug: 'annadhanam-corpus-fund', kind: 'corpus', amount: 0,\n    name: { en: 'Annadhanam Corpus Fund', ta: 'அன்னதான கார்பஸ் நிதி' } },\n];\n\nexport const getDonation = (slug: string) => DONATIONS.find((d) => d.slug === slug);\n","src/lib/cartItem.ts":"import type { Locale } from './i18n';\nimport { getSeva, txt } from '@/data/sevas';\nimport { getDonation } from '@/data/donations';\n\n// The cart holds two kinds of lines: sevas and donations. Each has its own payment gateway later.\nexport type Stream = 'seva' | 'donation';\nexport const STREAMS: Stream[] = ['seva', 'donation'];\nexport const parseStream = (v: string | string[] | undefined): Stream => (v === 'donation' ? 'donation' : 'seva');\n\n// Lines saved before donations existed have no stream, so they are sevas\nexport const streamOf = (l: { stream?: Stream }): Stream => l.stream ?? 'seva';\n\nexport type ItemInfo = {\n  name: string;\n  href: string;          // detail page\n  photo: string;         // CSS background-image\n  fixedPrice: boolean;   // false = the buyer chose the amount\n  maxQty: number;\n};\n\nconst FALLBACK = 'linear-gradient(135deg, #7A1C1C 0%, #D97706 140%)';\n\nexport function itemInfo(stream: Stream, slug: string, locale: Locale): ItemInfo {\n  if (stream === 'donation') {\n    const d = getDonation(slug);\n    return {\n      name: d ? txt(d.name, locale) : slug,\n      href: `/${locale}/donate/${slug}`,\n      photo: FALLBACK,\n      fixedPrice: d ? d.amount > 0 : false,\n      maxQty: d?.maxQty ?? 10,\n    };\n  }\n  const s = getSeva(slug);\n  return {\n    name: s ? txt(s.name, locale) : slug,\n    href: `/${locale}/sevas/${slug}`,\n    photo: `url('/images/sevas/${slug}.jpg'), ${FALLBACK}`,\n    fixedPrice: s ? s.amount > 0 : false,\n    maxQty: s?.maxQty ?? 10,\n  };\n}\n","src/components/DonationList.tsx":"'use client';\n\nimport { useMemo, useRef, useState } from 'react';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { txt } from '@/data/sevas';\nimport { DONATIONS, type Donation } from '@/data/donations';\nimport DonationCard from './donations/DonationCard';\nimport DonationPanel from './donations/DonationPanel';\n\ntype T = Dictionary['donate'];\ntype Tab = 'all' | 'donation' | 'corpus';\n\n// The donation catalogue: tabs (All / Donation List / Corpus Fund), search and sort, the cards,\n// and the donation panel on the right that opens when a card is picked.\nexport default function DonationList({ t, locale }: { t: T; locale: Locale }) {\n  const [tab, setTab] = useState<Tab>('all');\n  const [query, setQuery] = useState('');\n  const [sort, setSort] = useState('default');\n  const [selected, setSelected] = useState<Donation | null>(null);\n  const panelRef = useRef<HTMLDivElement>(null);\n\n  const counts: Record<Tab, number> = {\n    all: DONATIONS.length,\n    donation: DONATIONS.filter((d) => d.kind === 'donation').length,\n    corpus: DONATIONS.filter((d) => d.kind === 'corpus').length,\n  };\n\n  const shown = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    const list = DONATIONS.filter((d) => (tab === 'all' || d.kind === tab) && (!q || txt(d.name, locale).toLowerCase().includes(q)));\n    if (sort === 'low') return [...list].sort((a, b) => (a.amount || Infinity) - (b.amount || Infinity));\n    if (sort === 'high') return [...list].sort((a, b) => b.amount - a.amount);\n    return list;\n  }, [tab, query, sort, locale]);\n\n  function pick(d: Donation) {\n    setSelected(d);\n    // On a phone the panel sits below the cards, so bring it into view\n    if (typeof window !== 'undefined' && !window.matchMedia('(min-width: 1024px)').matches) {\n      panelRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });\n    }\n  }\n\n  const reset = () => {\n    setTab('all');\n    setQuery('');\n    setSort('default');\n  };\n\n  const tabs: { key: Tab; label: string }[] = [\n    { key: 'all', label: t.tabAll },\n    { key: 'donation', label: t.tabDonation },\n    { key: 'corpus', label: t.tabCorpus },\n  ];\n\n  return (\n    <div id=\"donation-list\" className=\"scroll-mt-24\">\n      <div role=\"group\" aria-label={t.tabsLabel} className=\"flex flex-wrap gap-3\">\n        {tabs.map((x) => {\n          const on = tab === x.key;\n          return (\n            <button\n              key={x.key}\n              type=\"button\"\n              aria-pressed={on}\n              onClick={() => setTab(x.key)}\n              className={`rounded-md border px-5 py-2 text-sm font-bold transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${on ? 'border-maroon bg-maroon text-white' : 'border-maroon/30 bg-white text-maroon hover:bg-rose'}`}\n            >\n              {x.label} <span className={on ? 'text-rose' : 'text-charcoal/60'}>({counts[x.key]})</span>\n            </button>\n          );\n        })}\n      </div>\n\n      <div className=\"mt-8 flex flex-col gap-8 lg:flex-row lg:items-start\">\n        <div className=\"min-w-0 flex-1\">\n          <h2 className=\"font-display text-3xl font-semibold text-maroon sm:text-4xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-2xl [html[lang='ta']_&]:sm:text-3xl\">\n            {tab === 'corpus' ? t.catalogTitleCorpus : t.catalogTitle}\n          </h2>\n\n          <div className=\"mt-5 flex flex-col gap-3 sm:flex-row\">\n            <label className=\"block sm:flex-1\">\n              <span className=\"sr-only\">{t.searchLabel}</span>\n              <input type=\"search\" value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t.searchPlaceholder} className=\"w-full rounded-md border border-rose bg-white px-4 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none focus-visible:ring-2 focus-visible:ring-saffron/40\" />\n            </label>\n            <label className=\"block sm:w-52\">\n              <span className=\"sr-only\">{t.sortLabel}</span>\n              <select value={sort} onChange={(e) => setSort(e.target.value)} className=\"w-full rounded-md border border-rose bg-white px-3 py-2.5 text-charcoal focus:border-saffron focus:outline-none focus-visible:ring-2 focus-visible:ring-saffron/40\">\n                {t.sortOptions.map((o) => (\n                  <option key={o.key} value={o.key}>{o.label}</option>\n                ))}\n              </select>\n            </label>\n          </div>\n\n          <p role=\"status\" className=\"mt-4 text-sm font-semibold text-charcoal/70\">{t.countLabel.replace('{n}', String(shown.length))}</p>\n\n          {shown.length > 0 ? (\n            <ul className=\"mt-4 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2\">\n              {shown.map((d) => (\n                <li key={d.slug} className=\"h-full\">\n                  <DonationCard item={d} locale={locale} t={t} selected={selected?.slug === d.slug} onSelect={() => pick(d)} />\n                </li>\n              ))}\n            </ul>\n          ) : (\n            <div className=\"mt-6 rounded-2xl bg-rose/50 px-6 py-12 text-center\">\n              <p className=\"font-serif text-lg text-charcoal\">{t.noResults}</p>\n              <button type=\"button\" onClick={reset} className=\"mt-4 rounded-md bg-maroon px-5 py-2.5 font-semibold text-white hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.clearFilters}</button>\n            </div>\n          )}\n        </div>\n\n        <div ref={panelRef} className=\"scroll-mt-24 p-1 lg:sticky lg:top-24 lg:max-h-[calc(100vh-7rem)] lg:w-96 lg:shrink-0 lg:overflow-y-auto\">\n          <DonationPanel item={selected} locale={locale} t={t} onChange={() => setSelected(null)} />\n        </div>\n      </div>\n    </div>\n  );\n}\n","src/components/donations/DonationCard.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { rupees } from '@/lib/format';\nimport { txt } from '@/data/sevas';\nimport type { Donation } from '@/data/donations';\n\n// One donation in the list: name, amount, and the button that opens the donation panel\nexport default function DonationCard({\n  item,\n  locale,\n  t,\n  selected,\n  onSelect,\n}: {\n  item: Donation;\n  locale: Locale;\n  t: Dictionary['donate'];\n  selected: boolean;\n  onSelect: () => void;\n}) {\n  const closed = item.status !== 'open';\n  return (\n    <article className={`flex h-full flex-col rounded-xl bg-white p-5 shadow-sm transition-shadow ${selected ? 'shadow-md ring-2 ring-saffron' : 'ring-1 ring-rose hover:shadow-md'}`}>\n      <div className=\"flex items-start justify-between gap-3\">\n        <h3 className=\"font-display text-xl font-semibold leading-tight text-maroon [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-lg\">\n          <Link href={`/${locale}/donate/${item.slug}`} className=\"underline-offset-4 hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">\n            {txt(item.name, locale)}\n          </Link>\n        </h3>\n        <p className=\"shrink-0 text-right font-display text-xl font-semibold leading-tight text-saffron [html[lang='ta']_&]:text-base\">\n          {item.amount > 0 ? rupees(item.amount) : t.abilityShort}\n        </p>\n      </div>\n\n      <div className=\"mt-auto pt-5\">\n        <button\n          type=\"button\"\n          disabled={closed}\n          aria-pressed={selected}\n          onClick={onSelect}\n          className={`w-full rounded-md border px-4 py-2.5 text-sm font-bold transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${\n            closed\n              ? 'cursor-not-allowed border-rose bg-rose/60 text-charcoal/60'\n              : selected\n                ? 'border-saffron bg-saffron text-charcoal'\n                : 'border-saffron bg-white text-maroon hover:bg-saffron/15'\n          }`}\n        >\n          {closed ? t.closedLabel : selected ? `✓ ${t.selected}` : t.addToDonationCart}\n        </button>\n      </div>\n    </article>\n  );\n}\n","src/components/donations/DonationPanel.tsx":"'use client';\n\nimport { useEffect, useId, useRef, useState } from 'react';\nimport Link from 'next/link';\nimport { useRouter } from 'next/navigation';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { rupees } from '@/lib/format';\nimport { txt } from '@/data/sevas';\nimport type { Donation } from '@/data/donations';\nimport { useCart } from '@/components/cart/CartProvider';\n\ntype T = Dictionary['donate'];\n\nconst STORE = 'vedaneri.donor.v1';\nconst readName = () => {\n  try {\n    return window.localStorage.getItem(STORE) ?? '';\n  } catch {\n    return '';\n  }\n};\nconst writeName = (v: string) => {\n  try {\n    window.localStorage.setItem(STORE, v);\n  } catch {\n    /* ignore: storage can be blocked */\n  }\n};\n\nconst inputClass = 'w-full rounded-md border-2 border-rose bg-white px-4 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none';\nconst btnPrimary = 'rounded-md bg-maroon px-5 py-3 text-center font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron';\nconst btnGhost = 'rounded-md border-2 border-rose bg-white px-5 py-3 text-center font-semibold text-charcoal transition-colors hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron';\n\n// Donation panel: donor name, amount (or quantity), then add to the cart.\n// On the list page the donation comes from the card the visitor picked; on a detail page it is fixed.\nexport default function DonationPanel({\n  item,\n  locale,\n  t,\n  fixed = false,\n  onChange,\n}: {\n  item: Donation | null;\n  locale: Locale;\n  t: T;\n  fixed?: boolean;\n  onChange?: () => void;\n}) {\n  const router = useRouter();\n  const { add, contact } = useCart();\n  const headingId = useId();\n  const headingRef = useRef<HTMLHeadingElement>(null);\n  const firstRender = useRef(true);\n\n  const [donor, setDonor] = useState('');\n  const [amountStr, setAmountStr] = useState('');\n  const [qty, setQty] = useState(1);\n  const [errors, setErrors] = useState<Record<string, string>>({});\n  const [added, setAdded] = useState<string | null>(null);\n\n  // Start from the name used last time, or the name given at checkout\n  useEffect(() => {\n    setDonor((d) => d || readName() || contact.name);\n  }, [contact.name]);\n\n  // A different donation was picked: clean amount and quantity\n  useEffect(() => {\n    setAmountStr('');\n    setQty(1);\n    setErrors({});\n    if (item) setAdded(null);\n  }, [item]);\n\n  // Move focus to the heading when the panel changes, so screen-reader users hear it (not on first load)\n  useEffect(() => {\n    if (firstRender.current) {\n      firstRender.current = false;\n      return;\n    }\n    headingRef.current?.focus();\n  }, [item, added]);\n\n  const choose = !!item && item.amount === 0;\n  const unit = item ? (choose ? Number(amountStr) || 0 : item.amount) : 0;\n  const total = unit * (choose ? 1 : qty);\n\n  function submit(goToCart: boolean) {\n    if (!item || item.status !== 'open') return;\n    const e: Record<string, string> = {};\n    if (!donor.trim()) e.donor = t.errName;\n    if (choose && !(Number(amountStr) >= item.minAmount)) e.amount = t.errAmount.replace('{min}', rupees(item.minAmount));\n    setErrors(e);\n    if (Object.keys(e).length) return;\n\n    add({ stream: 'donation', slug: item.slug, qty: choose ? 1 : qty, unit, date: '', devotee: donor.trim(), gotram: '', nakshatram: '' });\n    writeName(donor.trim());\n    if (goToCart) {\n      router.push(`/${locale}/cart`);\n      return;\n    }\n    setAdded(txt(item.name, locale));\n    onChange?.(); // on the list page this clears the picked donation so the panel returns to its first state\n  }\n\n  const title = item ? t.panelTitleForm : t.panelTitle;\n  const text = item ? t.panelTextForm : t.panelText;\n\n  return (\n    <section aria-labelledby={headingId} className=\"rounded-2xl bg-white p-6 shadow-lg ring-1 ring-rose\">\n      <h2 id={headingId} ref={headingRef} tabIndex={-1} className=\"font-display text-3xl font-semibold leading-tight text-maroon break-words focus:outline-none [html[lang='ta']_&]:!leading-[1.35] [html[lang='ta']_&]:text-xl\">\n        {title}\n      </h2>\n      <p className=\"mt-1 text-sm text-charcoal/70\">{text}</p>\n\n      {added !== null && (\n        <div role=\"status\" className=\"mt-6 rounded-xl bg-saffron/15 p-5 text-center\">\n          <p className=\"font-display text-2xl font-semibold text-maroon\">✓ {t.added}</p>\n          <p className=\"mt-1 text-charcoal\">{added}</p>\n          <div className=\"mt-4 flex flex-col gap-3\">\n            <Link href={`/${locale}/cart`} className={btnPrimary}>{t.viewCart}</Link>\n            {fixed ? (\n              <Link href={`/${locale}/donate`} className={btnGhost}>{t.keepBrowsing}</Link>\n            ) : (\n              <button type=\"button\" onClick={() => setAdded(null)} className={btnGhost}>{t.chooseAnother}</button>\n            )}\n          </div>\n        </div>\n      )}\n\n      {added === null && !item && <p className=\"mt-6 rounded-xl bg-rose/50 p-5 text-center font-serif text-charcoal/85\">{t.panelEmpty}</p>}\n\n      {added === null && item && (\n        <form noValidate onSubmit={(ev) => { ev.preventDefault(); submit(false); }} className=\"mt-5\">\n          <div className=\"flex items-start justify-between gap-3 rounded-lg bg-rose/50 p-3\">\n            <div className=\"min-w-0\">\n              <p className=\"font-semibold leading-snug text-charcoal\">{txt(item.name, locale)}</p>\n              <p className=\"text-sm text-charcoal/75\">{item.amount > 0 ? rupees(item.amount) : t.abilityLabel}</p>\n            </div>\n            {!fixed && (\n              <button type=\"button\" onClick={onChange} className=\"shrink-0 text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal\">{t.change}</button>\n            )}\n          </div>\n\n          <div className=\"mt-5\">\n            <label htmlFor=\"donor\" className=\"block text-sm font-bold text-charcoal\">{t.donorName} <span aria-hidden=\"true\" className=\"text-maroon\">*</span></label>\n            <input id=\"donor\" value={donor} onChange={(e) => { setDonor(e.target.value); if (errors.donor) setErrors((x) => ({ ...x, donor: '' })); }} autoComplete=\"name\" aria-invalid={!!errors.donor} aria-describedby={errors.donor ? 'donor-error' : 'donor-hint'} className={`mt-1 ${inputClass}`} />\n            {errors.donor ? <p id=\"donor-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors.donor}</p> : <p id=\"donor-hint\" className=\"mt-1 text-sm text-charcoal/70\">{t.donorHelp}</p>}\n          </div>\n\n          {choose ? (\n            <div className=\"mt-5\">\n              <label htmlFor=\"d-amount\" className=\"block text-sm font-bold text-charcoal\">{t.amountInput} <span aria-hidden=\"true\" className=\"text-maroon\">*</span></label>\n              <div className=\"relative mt-1\">\n                <span aria-hidden=\"true\" className=\"pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 font-bold text-charcoal/70\">₹</span>\n                <input id=\"d-amount\" type=\"number\" inputMode=\"numeric\" min={item.minAmount} step={1} value={amountStr} onChange={(e) => { setAmountStr(e.target.value); if (errors.amount) setErrors((x) => ({ ...x, amount: '' })); }} aria-invalid={!!errors.amount} aria-describedby={errors.amount ? 'd-amount-error' : 'd-amount-hint'} className={`${inputClass} pl-9`} />\n              </div>\n              {errors.amount ? <p id=\"d-amount-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors.amount}</p> : <p id=\"d-amount-hint\" className=\"mt-1 text-sm text-charcoal/70\">{t.amountHelp}</p>}\n            </div>\n          ) : (\n            <div className=\"mt-5\">\n              <p className=\"text-sm font-bold text-charcoal\">{t.qtyLabel}</p>\n              <div className=\"mt-1 inline-flex items-center rounded-md border-2 border-rose\" role=\"group\" aria-label={t.qtyLabel}>\n                <button type=\"button\" aria-label={t.decrease} disabled={qty <= 1} onClick={() => setQty((q) => Math.max(1, q - 1))} className=\"h-11 w-11 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">−</button>\n                <span aria-live=\"polite\" className=\"w-12 text-center text-lg font-bold\">{qty}</span>\n                <button type=\"button\" aria-label={t.increase} disabled={qty >= item.maxQty} onClick={() => setQty((q) => Math.min(item.maxQty, q + 1))} className=\"h-11 w-11 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">+</button>\n              </div>\n            </div>\n          )}\n\n          <p className=\"mt-5 flex items-baseline justify-between border-t-2 border-rose pt-4\">\n            <span className=\"font-bold text-charcoal\">{t.totalLabel}</span>\n            <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</span>\n          </p>\n\n          <div className=\"mt-5 flex flex-col gap-3\">\n            <button type=\"submit\" className={btnPrimary}>{t.addToDonationCart}</button>\n            <button type=\"button\" onClick={() => submit(true)} className={btnGhost}>{t.addAndGo}</button>\n          </div>\n        </form>\n      )}\n    </section>\n  );\n}\n","src/app/[locale]/donate/page.tsx":"import type { Metadata } from 'next';\nimport Link from 'next/link';\nimport { notFound } from 'next/navigation';\nimport DonationList from '@/components/DonationList';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return {\n    title: `${t.donate.meta.title} | ${t.site.name}`,\n    description: t.donate.meta.description,\n  };\n}\n\n// Hero photo: apps/web/public/images/hero-bg.jpg\n// On desktop the photo fills the right two thirds of the banner, so Swamiji stays on the right and the text sits on the dark left side.\n// BG_POSITION decides which part of the photo is visible: first number = left/right (0% left edge, 100% right edge),\n// second number = up/down (0% top, 100% bottom). Raise the second number to show more of the lower part (Swamiji).\nconst BG_POSITION = '50% 70%';\n// On phones the photo fills the whole banner; this keeps Swamiji in the middle.\nconst BG_POSITION_MOBILE = '46% 65%';\n\nfunction Flame({ className = '' }: { className?: string }) {\n  return (\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\" className={`shrink-0 ${className}`}>\n      <path d=\"M12 2c.6 3.2 4.5 5.4 4.5 10a4.5 4.5 0 0 1-9 0c0-2 .9-3.2 1.8-4.4.4 1.2 1 1.8 1.7 2C11.3 7.7 11.6 5 12 2z\" />\n    </svg>\n  );\n}\n\nfunction Arrow() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" className=\"transition-transform duration-300 group-hover:translate-x-1.5\">\n      <path d=\"M5 12h14M13 6l6 6-6 6\" />\n    </svg>\n  );\n}\n\nexport default async function DonatePage({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.donate;\n  const href = (p: string) => `/${locale}${p}`;\n\n  return (\n    <main>\n      {/* 1. Hero: the hero-bg.jpg photo as the background, with the title and buttons on the dark left side */}\n      <section aria-labelledby=\"donate-title\" className=\"relative isolate overflow-hidden bg-charcoal text-white\">\n        {/* Photo: whole banner on phones, right two thirds on desktop (the left side stays plain dark for the text) */}\n        <div aria-hidden=\"true\" className=\"absolute inset-0 -z-20 bg-cover bg-no-repeat lg:hidden\" style={{ backgroundImage: \"url('/images/hero-bg.jpg')\", backgroundPosition: BG_POSITION_MOBILE }} />\n        <div aria-hidden=\"true\" className=\"absolute inset-y-0 left-1/3 right-0 -z-20 hidden bg-cover bg-no-repeat lg:block\" style={{ backgroundImage: \"url('/images/hero-bg.jpg')\", backgroundPosition: BG_POSITION }} />\n\n        {/* Readability layers. Phones: the whole photo is darkened. Desktop: the photo fades into the dark left side. */}\n        <div aria-hidden=\"true\" className=\"absolute inset-0 -z-10 bg-charcoal/65 lg:hidden\" />\n        <div aria-hidden=\"true\" className=\"absolute inset-0 -z-10 hidden bg-gradient-to-r from-charcoal from-33% via-charcoal/60 via-50% to-charcoal/0 to-75% lg:block\" />\n        <div aria-hidden=\"true\" className=\"absolute inset-0 -z-10 bg-gradient-to-t from-charcoal/50 via-transparent to-charcoal/30\" />\n\n        <nav aria-label={t.crumbLabel} className=\"mx-auto max-w-7xl px-4 pt-6 text-sm text-white/80 lg:px-8\">\n          <ol className=\"flex flex-wrap items-center gap-2\">\n            <li><Link href={href('')} className=\"underline-offset-4 hover:text-white hover:underline\">{dict.nav.home}</Link></li>\n            <li aria-hidden=\"true\">/</li>\n            <li aria-current=\"page\" className=\"font-semibold text-white\">{dict.nav.donations}</li>\n          </ol>\n        </nav>\n\n        <div className=\"mx-auto flex max-w-7xl items-center px-4 pb-24 pt-10 sm:pb-28 lg:min-h-[520px] lg:px-8 lg:pb-32\">\n          <div className=\"mx-auto w-full min-w-0 max-w-2xl text-center lg:mx-0 lg:max-w-[40rem] lg:text-left\">\n            <p className=\"inline-flex max-w-full items-center gap-2 rounded-full border border-saffron/70 bg-charcoal/50 px-4 py-1.5 text-sm font-semibold text-white backdrop-blur-sm sm:text-base\">\n              <Flame className=\"text-saffron\" />\n              <span>{t.eyebrow}</span>\n            </p>\n            <h1 id=\"donate-title\" className=\"animate-fade-up mt-5 font-display text-5xl font-semibold leading-[1.1] !text-white drop-shadow-[0_2px_14px_rgba(0,0,0,0.6)] motion-reduce:animate-none sm:text-6xl lg:text-7xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-4xl [html[lang='ta']_&]:sm:text-5xl [html[lang='ta']_&]:lg:text-6xl\">{t.title}</h1>\n            <div aria-hidden=\"true\" className=\"mt-4 flex items-center justify-center gap-3 lg:justify-start\">\n              <span className=\"h-px w-14 bg-saffron\" />\n              <span className=\"h-2 w-2 rotate-45 bg-saffron\" />\n              <span className=\"h-px w-14 bg-saffron\" />\n            </div>\n            <p className=\"mt-5 font-serif text-lg leading-relaxed text-white/95 drop-shadow-[0_1px_8px_rgba(0,0,0,0.6)] sm:text-xl\">{t.intro}</p>\n\n            <div className=\"mt-8 flex flex-wrap justify-center gap-3 lg:justify-start\">\n              <a href=\"#donation-list\" className=\"group inline-flex items-center gap-2 rounded-full bg-saffron px-6 py-2.5 font-semibold text-charcoal transition-colors hover:bg-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white\">\n                {t.listLabel}\n                <Arrow />\n              </a>\n              <Link href={href('/cart')} className=\"inline-flex items-center rounded-full border-2 border-white/70 px-6 py-2.5 font-semibold text-white transition-colors hover:bg-white hover:text-maroon focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white\">\n                {dict.shop.cartTitle}\n              </Link>\n            </div>\n          </div>\n        </div>\n\n        {/* Soft wave into the white section below */}\n        <svg aria-hidden=\"true\" viewBox=\"0 0 1440 40\" preserveAspectRatio=\"none\" className=\"absolute inset-x-0 bottom-0 h-8 w-full text-white sm:h-10\">\n          <path d=\"M0 40V18C240 -2 480 -2 720 14S1200 34 1440 12V40Z\" fill=\"currentColor\" />\n        </svg>\n      </section>\n\n      {/* 2. Seva list: tabs, cards and the booking panel */}\n      <section aria-label={t.listLabel} className=\"bg-white pb-16 pt-6 sm:pb-20\">\n        <div className=\"mx-auto max-w-7xl px-4 lg:px-8\">\n          <DonationList t={t} locale={locale} />\n        </div>\n      </section>\n\n      {/* 3. Help */}\n      <section aria-labelledby=\"help-title\" className=\"bg-saffron py-10 text-charcoal sm:py-12\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-6 px-4 text-center lg:flex-row lg:justify-between lg:px-8 lg:text-left\">\n          <div className=\"max-w-2xl\">\n            <h2 id=\"help-title\" className=\"font-display text-3xl font-semibold leading-tight !text-charcoal sm:text-4xl\">{t.helpTitle}</h2>\n            <p className=\"mt-2 text-lg\">{t.helpText}</p>\n          </div>\n          <Link\n            href={href('/contact')}\n            className=\"group inline-flex items-center gap-2 rounded-md bg-charcoal px-7 py-3 font-semibold text-white transition-colors hover:bg-maroon focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-charcoal\"\n          >\n            {t.helpCta}\n            <Arrow />\n          </Link>\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/donate/[slug]/page.tsx":"import type { Metadata } from 'next';\nimport Link from 'next/link';\nimport { notFound } from 'next/navigation';\nimport DonationPanel from '@/components/donations/DonationPanel';\nimport SectionTitle from '@/components/SectionTitle';\nimport { DONATIONS, getDonation } from '@/data/donations';\nimport { txt } from '@/data/sevas';\nimport { getDictionary } from '@/lib/dictionary';\nimport { rupees } from '@/lib/format';\nimport { isLocale, locales } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string; slug: string }> };\n\nexport const dynamicParams = false;\nexport const generateStaticParams = () => locales.flatMap((locale) => DONATIONS.map((d) => ({ locale, slug: d.slug })));\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale, slug } = await params;\n  const item = getDonation(slug);\n  if (!isLocale(locale) || !item) return {};\n  const t = getDictionary(locale);\n  return { title: `${txt(item.name, locale)} | ${t.site.name}` };\n}\n\nexport default async function DonationDetailPage({ params }: Params) {\n  const { locale, slug } = await params;\n  if (!isLocale(locale)) notFound();\n  const item = getDonation(slug);\n  if (!item) notFound();\n\n  const dict = getDictionary(locale);\n  const t = dict.donate;\n  const name = txt(item.name, locale);\n  const kindLabel = item.kind === 'corpus' ? t.tabCorpus : t.tabDonation;\n  const paragraphs = item.description[locale];\n  const related = DONATIONS.filter((d) => d.kind === item.kind && d.slug !== item.slug).slice(0, 3);\n  const href = (p: string) => `/${locale}${p}`;\n\n  return (\n    <main>\n      <section className=\"bg-gradient-to-b from-rose/80 to-white\">\n        <nav aria-label={t.crumbLabel} className=\"mx-auto max-w-6xl px-4 pb-2 pt-6 text-sm text-charcoal/80 lg:px-8\">\n          <ol className=\"flex flex-wrap items-center gap-2\">\n            <li><Link href={href('')} className=\"underline-offset-4 hover:text-maroon hover:underline\">{dict.nav.home}</Link></li>\n            <li aria-hidden=\"true\">/</li>\n            <li><Link href={href('/donate')} className=\"underline-offset-4 hover:text-maroon hover:underline\">{dict.nav.donations}</Link></li>\n            <li aria-hidden=\"true\">/</li>\n            <li aria-current=\"page\" className=\"font-semibold text-maroon\">{name}</li>\n          </ol>\n        </nav>\n      </section>\n\n      {/* Details on the left, donation form on the right */}\n      <section className=\"bg-white pb-12 pt-4 sm:pb-16\">\n        <div className=\"mx-auto grid max-w-6xl items-start gap-10 px-4 lg:grid-cols-2 lg:gap-14 lg:px-8\">\n          <div>\n            <p className=\"inline-block rounded-full bg-maroon px-4 py-1 text-xs font-bold uppercase tracking-wider text-white [html[lang='ta']_&]:tracking-normal\">{kindLabel}</p>\n            <h1 className=\"mt-3 font-display text-4xl font-semibold leading-tight text-maroon sm:text-5xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-3xl [html[lang='ta']_&]:sm:text-4xl\">{name}</h1>\n\n            <dl className=\"mt-5 rounded-xl bg-rose/50 p-5\">\n              <dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.amountLabel}</dt>\n              <dd className=\"mt-1 font-display text-3xl font-semibold text-charcoal\">\n                {item.amount > 0 ? rupees(item.amount) : <span className=\"text-2xl text-saffron [html[lang='ta']_&]:text-xl\">{t.abilityLabel}</span>}\n              </dd>\n            </dl>\n\n            <h2 className=\"mt-8 font-display text-2xl font-semibold text-maroon\">{t.aboutTitle}</h2>\n            {paragraphs.length > 0 ? (\n              paragraphs.map((p) => <p key={p} className=\"mt-3 font-serif text-lg leading-relaxed text-charcoal\">{p}</p>)\n            ) : (\n              <p className=\"mt-3 font-serif text-lg leading-relaxed text-charcoal/80\">{t.descriptionEmpty}</p>\n            )}\n          </div>\n\n          <div className=\"lg:sticky lg:top-24\">\n            <DonationPanel item={item} locale={locale} t={t} fixed />\n          </div>\n        </div>\n      </section>\n\n      {related.length > 0 && (\n        <section aria-labelledby=\"related-title\" className=\"bg-rose/50 py-12 sm:py-16\">\n          <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n            <SectionTitle id=\"related-title\" title={t.relatedTitle} />\n            <ul className=\"mt-10 grid gap-6 sm:grid-cols-2 lg:grid-cols-3\">\n              {related.map((d) => (\n                <li key={d.slug} className=\"h-full\">\n                  <Link href={href(`/donate/${d.slug}`)} className=\"flex h-full flex-col rounded-xl bg-white p-5 shadow-sm ring-1 ring-rose transition-shadow hover:shadow-md focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">\n                    <span className=\"font-display text-xl font-semibold leading-tight text-maroon [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-lg\">{txt(d.name, locale)}</span>\n                    <span className=\"mt-auto pt-4 font-display text-xl font-semibold text-saffron\">{d.amount > 0 ? rupees(d.amount) : t.abilityShort}</span>\n                  </Link>\n                </li>\n              ))}\n            </ul>\n            <p className=\"mt-8 text-center\">\n              <Link href={href('/donate')} className=\"font-bold text-maroon underline underline-offset-4\">{t.backLabel}</Link>\n            </p>\n          </div>\n        </section>\n      )}\n    </main>\n  );\n}\n","src/components/cart/CartProvider.tsx":"'use client';\n\n// The cart lives in the browser (localStorage) while the site is UI-only.\n// When the backend is ready, replace the read/write calls below with API calls.\n\nimport type { FamilyMember } from '@/data/sankalpam';\nimport { streamOf, type Stream } from '@/lib/cartItem';\nimport { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';\n\nexport type CartLine = {\n  id: string;\n  stream?: Stream;    // 'seva' (default, also for lines saved earlier) or 'donation'\n  slug: string;\n  qty: number;\n  unit: number;       // amount for one, in rupees\n  date: string;       // YYYY-MM-DD (empty for donations)\n  devotee: string;    // devotee name for a seva, donor name for a donation\n  gotram: string;\n  nakshatram: string;\n  rasi?: string;                 // moon sign (optional, added with the sankalpam form)\n  family?: FamilyMember[];       // family members named in the sankalpam\n};\n\nexport type Contact = { name: string; phone: string; email: string; address: string; city: string; state: string; pin: string; country: string };\nexport const EMPTY_CONTACT: Contact = { name: '', phone: '', email: '', address: '', city: '', state: '', pin: '', country: 'India' };\n\nexport type Order = { id: string; stream: Stream; placedAt: string; lines: CartLine[]; total: number; contact: Contact; method: string };\n\nconst KEY_CART = 'vedaneri.cart.v1';\nconst KEY_CONTACT = 'vedaneri.contact.v1';\nconst KEY_ORDER = 'vedaneri.order.v1';\n\n// Browser storage can be blocked or empty (private windows), so every call is wrapped.\nfunction read<T>(key: string, fallback: T): T {\n  try {\n    const raw = window.localStorage.getItem(key);\n    return raw ? (JSON.parse(raw) as T) : fallback;\n  } catch {\n    return fallback;\n  }\n}\nfunction write(key: string, value: unknown) {\n  try {\n    window.localStorage.setItem(key, JSON.stringify(value));\n  } catch {\n    /* ignore */\n  }\n}\n\ntype CartContextValue = {\n  ready: boolean;                 // false until the saved cart has been read\n  lines: CartLine[];\n  count: number;                  // number of items in the whole cart (quantities added up)\n  total: number;                  // all lines together\n  linesOf: (stream: Stream) => CartLine[];\n  totalOf: (stream: Stream) => number;\n  add: (line: Omit<CartLine, 'id'>) => void;\n  setQty: (id: string, qty: number) => void;\n  remove: (id: string) => void;\n  contact: Contact;\n  saveContact: (c: Contact) => void;\n  order: Order | null;            // the last paid order\n  placeOrder: (method: string, stream: Stream) => Order | null;  // pays one section only\n};\n\nconst CartContext = createContext<CartContextValue | null>(null);\n\nexport function useCart() {\n  const ctx = useContext(CartContext);\n  if (!ctx) throw new Error('useCart must be used inside <CartProvider>');\n  return ctx;\n}\n\nexport default function CartProvider({ children }: { children: ReactNode }) {\n  const [ready, setReady] = useState(false);\n  const [lines, setLines] = useState<CartLine[]>([]);\n  const [contact, setContact] = useState<Contact>(EMPTY_CONTACT);\n  const [order, setOrder] = useState<Order | null>(null);\n\n  useEffect(() => {\n    setLines(read<CartLine[]>(KEY_CART, []));\n    setContact({ ...EMPTY_CONTACT, ...read<Partial<Contact>>(KEY_CONTACT, {}) });\n    setOrder(read<Order | null>(KEY_ORDER, null));\n    setReady(true);\n  }, []);\n\n  useEffect(() => {\n    if (!ready) return;\n    write(KEY_CART, lines);\n    write(KEY_CONTACT, contact);\n    write(KEY_ORDER, order);\n  }, [ready, lines, contact, order]);\n\n  const add = useCallback((line: Omit<CartLine, 'id'>) => {\n    const id = `${line.slug}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;\n    setLines((l) => [...l, { ...line, id }]);\n  }, []);\n\n  const setQty = useCallback((id: string, qty: number) => {\n    setLines((l) => l.map((x) => (x.id === id ? { ...x, qty } : x)));\n  }, []);\n\n  const remove = useCallback((id: string) => setLines((l) => l.filter((x) => x.id !== id)), []);\n\n  const saveContact = useCallback((c: Contact) => setContact(c), []);\n\n  const total = useMemo(() => lines.reduce((s, l) => s + l.unit * l.qty, 0), [lines]);\n  const count = useMemo(() => lines.reduce((s, l) => s + l.qty, 0), [lines]);\n\n  const linesOf = useCallback((stream: Stream) => lines.filter((l) => streamOf(l) === stream), [lines]);\n  const totalOf = useCallback((stream: Stream) => linesOf(stream).reduce((s, l) => s + l.unit * l.qty, 0), [linesOf]);\n\n  // Pays one section (sevas or donations); the other section stays in the cart\n  const placeOrder = useCallback(\n    (method: string, stream: Stream) => {\n      const mine = lines.filter((l) => streamOf(l) === stream);\n      if (mine.length === 0) return null;\n      const d = new Date();\n      const stamp = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;\n      const o: Order = {\n        id: `VN-${stream === 'donation' ? 'D' : 'S'}-${stamp}-${Math.floor(1000 + Math.random() * 9000)}`,\n        stream,\n        placedAt: d.toISOString(),\n        lines: mine,\n        total: mine.reduce((s, l) => s + l.unit * l.qty, 0),\n        contact,\n        method,\n      };\n      setOrder(o);\n      setLines((all) => all.filter((l) => streamOf(l) !== stream));\n      return o;\n    },\n    [lines, contact],\n  );\n\n  const value = useMemo<CartContextValue>(\n    () => ({ ready, lines, count, total, linesOf, totalOf, add, setQty, remove, contact, saveContact, order, placeOrder }),\n    [ready, lines, count, total, linesOf, totalOf, add, setQty, remove, contact, saveContact, order, placeOrder],\n  );\n\n  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;\n}\n","src/components/cart/CartView.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees } from '@/lib/format';\nimport { itemInfo, type Stream } from '@/lib/cartItem';\nimport { GOTRAMS, NAKSHATRAMS, RASIS, RELATIONS, labelFor } from '@/data/sankalpam';\nimport { useCart } from './CartProvider';\n\n// One cart, two sections. Sevas and donations are paid separately (each has its own payment gateway).\nexport default function CartView({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const { ready, lines, linesOf, totalOf, setQty, remove } = useCart();\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (lines.length === 0) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-display text-3xl font-semibold text-maroon\">{t.cartEmpty}</p>\n        <p className=\"mt-2 font-serif text-lg text-charcoal/90\">{t.cartEmptyText}</p>\n        <div className=\"mt-6 flex flex-col justify-center gap-3 sm:flex-row\">\n          <Link href={href('/sevas')} className=\"rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.browse}</Link>\n          <Link href={href('/donate')} className=\"rounded-md border-2 border-maroon px-7 py-3 font-semibold text-maroon hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.browseDonations}</Link>\n        </div>\n      </div>\n    );\n  }\n\n  const sections: { stream: Stream; title: string; checkout: string; more: string; moreHref: string }[] = [\n    { stream: 'seva', title: t.sectionSeva, checkout: t.checkoutSeva, more: t.continueShopping, moreHref: href('/sevas') },\n    { stream: 'donation', title: t.sectionDonation, checkout: t.checkoutDonation, more: t.continueDonations, moreHref: href('/donate') },\n  ];\n\n  return (\n    <div className=\"space-y-12\">\n      {sections.map(({ stream, title, checkout, more, moreHref }) => {\n        const items = linesOf(stream);\n        if (items.length === 0) return null;\n        const count = items.reduce((s, l) => s + l.qty, 0);\n        const total = totalOf(stream);\n        return (\n          <section key={stream} aria-labelledby={`cart-${stream}`}>\n            <h2 id={`cart-${stream}`} className=\"font-display text-3xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.35] [html[lang='ta']_&]:text-2xl\">\n              {title} <span className=\"text-xl text-charcoal/60\">({count})</span>\n            </h2>\n            <div aria-hidden=\"true\" className=\"mb-5 mt-2 flex items-center gap-3\"><span className=\"h-px w-12 bg-saffron\" /><span className=\"h-2 w-2 rotate-45 bg-saffron\" /><span className=\"h-px w-12 bg-saffron\" /></div>\n\n            <div className=\"flex flex-col items-start gap-8 lg:flex-row\">\n              <ul className=\"w-full min-w-0 flex-1 space-y-4\">\n                {items.map((l) => {\n                  const info = itemInfo(stream, l.slug, locale);\n                  return (\n                    <li key={l.id} className=\"flex flex-col gap-4 rounded-2xl bg-white p-4 shadow-md ring-1 ring-rose sm:flex-row sm:p-5\">\n                      {stream === 'seva' && (\n                        <div role=\"img\" aria-label={info.name} className=\"h-32 w-full shrink-0 rounded-xl bg-maroon bg-cover bg-center sm:h-28 sm:w-36\" style={{ backgroundImage: info.photo }} />\n                      )}\n                      <div className=\"flex min-w-0 flex-1 flex-col\">\n                        <h3 className=\"font-display text-2xl font-semibold leading-tight text-maroon [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-xl\">\n                          <Link href={info.href} className=\"hover:underline\">{info.name}</Link>\n                        </h3>\n                        <dl className=\"mt-2 grid gap-x-6 gap-y-1 text-sm sm:grid-cols-2\">\n                          {l.date && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.dateLabel}:</dt><dd>{formatDate(l.date, locale)}</dd></div>}\n                          <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{stream === 'donation' ? t.donorLabel : t.devoteeLabel}:</dt><dd>{l.devotee}</dd></div>\n                          {l.gotram && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.gotramLabel}:</dt><dd>{labelFor(GOTRAMS, l.gotram, locale)}</dd></div>}\n                          {l.rasi && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.rasiLabel}:</dt><dd>{labelFor(RASIS, l.rasi, locale)}</dd></div>}\n                          {l.nakshatram && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.nakshatramLabel}:</dt><dd>{labelFor(NAKSHATRAMS, l.nakshatram, locale)}</dd></div>}\n                          {l.family && l.family.length > 0 && (\n                            <div className=\"flex gap-2 sm:col-span-2\"><dt className=\"font-bold text-charcoal/70\">{t.familyLabel}:</dt><dd>{l.family.map((m) => (m.relation ? `${m.name} (${labelFor(RELATIONS, m.relation, locale)})` : m.name)).join(', ')}</dd></div>\n                          )}\n                        </dl>\n\n                        <div className=\"mt-4 flex flex-wrap items-center justify-between gap-3\">\n                          {info.fixedPrice ? (\n                            <div className=\"inline-flex items-center rounded-md border-2 border-rose\" role=\"group\" aria-label={t.qtyLabel}>\n                              <button type=\"button\" aria-label={t.decrease} disabled={l.qty <= 1} onClick={() => setQty(l.id, l.qty - 1)} className=\"h-10 w-10 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">−</button>\n                              <span aria-live=\"polite\" className=\"w-10 text-center font-bold\">{l.qty}</span>\n                              <button type=\"button\" aria-label={t.increase} disabled={l.qty >= info.maxQty} onClick={() => setQty(l.id, l.qty + 1)} className=\"h-10 w-10 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">+</button>\n                            </div>\n                          ) : (\n                            <span className=\"text-sm text-charcoal/70\">{t.yourAmount}</span>\n                          )}\n                          <p className=\"font-display text-3xl font-semibold text-charcoal\">{rupees(l.qty * l.unit)}</p>\n                        </div>\n                        <button type=\"button\" onClick={() => remove(l.id)} className=\"mt-3 self-start text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-saffron\">{t.remove}</button>\n                      </div>\n                    </li>\n                  );\n                })}\n              </ul>\n\n              <aside aria-label={`${t.summaryTitle}: ${title}`} className=\"w-full rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose lg:sticky lg:top-24 lg:w-80 lg:shrink-0\">\n                <h3 className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.summaryTitle}</h3>\n                <dl className=\"mt-4 space-y-2\">\n                  <div className=\"flex justify-between\"><dt className=\"text-charcoal/80\">{title}</dt><dd className=\"font-semibold\">{count}</dd></div>\n                  <div className=\"flex items-baseline justify-between border-t-2 border-rose pt-4\">\n                    <dt className=\"font-bold\">{t.total}</dt>\n                    <dd className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</dd>\n                  </div>\n                </dl>\n                <Link href={href(`/checkout?stream=${stream}`)} className=\"mt-6 block rounded-md bg-maroon px-5 py-3 text-center font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{checkout}</Link>\n                <Link href={moreHref} className=\"mt-3 block text-center text-sm font-semibold text-maroon underline underline-offset-4\">{more}</Link>\n                <p className=\"mt-4 text-center text-xs text-charcoal/70\">{t.receiptNote}</p>\n              </aside>\n            </div>\n          </section>\n        );\n      })}\n      {linesOf('seva').length > 0 && linesOf('donation').length > 0 && (\n        <p className=\"rounded-xl bg-saffron/15 px-4 py-3 text-center text-sm font-semibold text-charcoal\">{t.twoPaymentsNote}</p>\n      )}\n    </div>\n  );\n}\n","src/components/cart/CheckoutForm.tsx":"'use client';\n\nimport { useState } from 'react';\nimport Link from 'next/link';\nimport { useRouter } from 'next/navigation';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport type { Stream } from '@/lib/cartItem';\nimport { useCart, type Contact } from './CartProvider';\nimport OrderSummary from './OrderSummary';\n\nconst inputClass =\n  'w-full rounded-md border-2 border-rose bg-white px-4 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none';\n\nfunction Field({ id, label, error, className = '', children }: { id: string; label: string; error?: string; className?: string; children: React.ReactNode }) {\n  return (\n    <div className={className}>\n      <label htmlFor={id} className=\"block text-sm font-bold text-charcoal\">{label}</label>\n      <div className=\"mt-1\">{children}</div>\n      {error && <p id={`${id}-error`} role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{error}</p>}\n    </div>\n  );\n}\n\nexport default function CheckoutForm({ t, locale, stream }: { t: Dictionary['shop']; locale: Locale; stream: Stream }) {\n  const router = useRouter();\n  const { ready, linesOf, totalOf, contact, saveContact } = useCart();\n  const lines = linesOf(stream);\n  const total = totalOf(stream);\n  const [form, setForm] = useState<Contact | null>(null);\n  const [errors, setErrors] = useState<Partial<Record<keyof Contact, string>>>({});\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (lines.length === 0) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-display text-3xl font-semibold text-maroon\">{t.cartEmpty}</p>\n        <Link href={href('/cart')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.backToCart}</Link>\n      </div>\n    );\n  }\n\n  // Start from what was saved the last time, then keep the visitor's edits\n  const v = form ?? contact;\n  const set = (k: keyof Contact) => (e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...v, [k]: e.target.value });\n\n  function submit(e: React.FormEvent) {\n    e.preventDefault();\n    const er: Partial<Record<keyof Contact, string>> = {};\n    if (!v.name.trim()) er.name = t.errName;\n    if (!/^\\+?[\\d\\s-]{7,15}$/.test(v.phone.trim())) er.phone = t.errPhone;\n    if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(v.email.trim())) er.email = t.errEmail;\n    if (!v.address.trim()) er.address = t.errAddress;\n    if (!v.city.trim()) er.city = t.errCity;\n    if (!v.state.trim()) er.state = t.errState;\n    if (!v.pin.trim()) er.pin = t.errPin;\n    if (!v.country.trim()) er.country = t.errCountry;\n    setErrors(er);\n    if (Object.keys(er).length) return;\n    saveContact({ ...v, name: v.name.trim(), phone: v.phone.trim(), email: v.email.trim() });\n    router.push(href(`/payment?stream=${stream}`));\n  }\n\n  const f = (k: keyof Contact) => ({ id: k, value: v[k], onChange: set(k), 'aria-invalid': !!errors[k], 'aria-describedby': errors[k] ? `${k}-error` : undefined, className: inputClass });\n\n  return (\n    <div className=\"grid items-start gap-8 lg:grid-cols-[1fr_360px]\">\n      <form noValidate onSubmit={submit} className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose sm:p-8\">\n        <h2 className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.contactTitle}</h2>\n        <p className=\"mt-1 text-sm text-charcoal/70\">{t.contactHelp}</p>\n\n        <div className=\"mt-6 grid gap-4 sm:grid-cols-2\">\n          <Field id=\"name\" label={t.fName} error={errors.name} className=\"sm:col-span-2\"><input {...f('name')} autoComplete=\"name\" /></Field>\n          <Field id=\"phone\" label={t.fPhone} error={errors.phone}><input {...f('phone')} type=\"tel\" autoComplete=\"tel\" inputMode=\"tel\" /></Field>\n          <Field id=\"email\" label={t.fEmail} error={errors.email}><input {...f('email')} type=\"email\" autoComplete=\"email\" /></Field>\n          <Field id=\"address\" label={t.fAddress} error={errors.address} className=\"sm:col-span-2\"><input {...f('address')} autoComplete=\"street-address\" /></Field>\n          <Field id=\"city\" label={t.fCity} error={errors.city}><input {...f('city')} autoComplete=\"address-level2\" /></Field>\n          <Field id=\"state\" label={t.fState} error={errors.state}><input {...f('state')} autoComplete=\"address-level1\" /></Field>\n          <Field id=\"pin\" label={t.fPin} error={errors.pin}><input {...f('pin')} autoComplete=\"postal-code\" /></Field>\n          <Field id=\"country\" label={t.fCountry} error={errors.country}><input {...f('country')} autoComplete=\"country-name\" /></Field>\n        </div>\n\n        <div className=\"mt-8 flex flex-col-reverse gap-3 sm:flex-row sm:justify-between\">\n          <Link href={href('/cart')} className=\"rounded-md border-2 border-maroon px-6 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backToCart}</Link>\n          <button type=\"submit\" className=\"rounded-md bg-maroon px-8 py-3 font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.continuePayment}</button>\n        </div>\n      </form>\n\n      <div className=\"lg:sticky lg:top-24\">\n        <OrderSummary stream={stream} lines={lines} total={total} locale={locale} t={t} />\n      </div>\n    </div>\n  );\n}\n","src/components/cart/OrderSummary.tsx":"import type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees } from '@/lib/format';\nimport { itemInfo, type Stream } from '@/lib/cartItem';\nimport type { CartLine } from './CartProvider';\n\n// Compact list of the items being paid for (one section of the cart), with the total. Used beside checkout and payment.\nexport default function OrderSummary({ stream, lines, total, locale, t }: { stream: Stream; lines: CartLine[]; total: number; locale: Locale; t: Dictionary['shop'] }) {\n  return (\n    <aside aria-label={t.summaryTitle} className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose\">\n      <h2 className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.summaryTitle}</h2>\n      <p className=\"mt-1 text-sm font-semibold text-charcoal/70\">{stream === 'donation' ? t.streamDonation : t.streamSeva}</p>\n      <ul className=\"mt-4 divide-y divide-rose\">\n        {lines.map((l) => {\n          const info = itemInfo(stream, l.slug, locale);\n          return (\n            <li key={l.id} className=\"flex gap-3 py-3\">\n              {stream === 'seva' && <div role=\"img\" aria-label=\"\" className=\"h-14 w-14 shrink-0 rounded-lg bg-maroon bg-cover bg-center\" style={{ backgroundImage: info.photo }} />}\n              <div className=\"min-w-0 flex-1\">\n                <p className=\"font-semibold leading-snug text-charcoal\">{info.name}</p>\n                <p className=\"text-sm text-charcoal/70\">{l.date ? `${formatDate(l.date, locale)} · ` : ''}{l.devotee}</p>\n                <p className=\"text-sm text-charcoal/70\">{l.qty} × {rupees(l.unit)}</p>\n              </div>\n              <p className=\"shrink-0 font-bold text-charcoal\">{rupees(l.qty * l.unit)}</p>\n            </li>\n          );\n        })}\n      </ul>\n      <p className=\"mt-2 flex items-baseline justify-between border-t-2 border-rose pt-4\">\n        <span className=\"font-bold text-charcoal\">{t.total}</span>\n        <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</span>\n      </p>\n    </aside>\n  );\n}\n","src/components/cart/PaymentView.tsx":"'use client';\n\nimport { useState } from 'react';\nimport Link from 'next/link';\nimport { useRouter } from 'next/navigation';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport type { Stream } from '@/lib/cartItem';\nimport { rupees } from '@/lib/format';\nimport { useCart } from './CartProvider';\nimport OrderSummary from './OrderSummary';\n\nexport default function PaymentView({ t, locale, stream }: { t: Dictionary['shop']; locale: Locale; stream: Stream }) {\n  const router = useRouter();\n  const { ready, linesOf, totalOf, contact, placeOrder } = useCart();\n  const lines = linesOf(stream);\n  const total = totalOf(stream);\n  const [method, setMethod] = useState('upi');\n  const [agree, setAgree] = useState(false);\n  const [error, setError] = useState('');\n  const [busy, setBusy] = useState(false);\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  // After a successful payment the cart is emptied, so do not show the \"empty\" message while moving on\n  if (lines.length === 0 && !busy) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-display text-3xl font-semibold text-maroon\">{t.cartEmpty}</p>\n        <Link href={href('/cart')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.backToCart}</Link>\n      </div>\n    );\n  }\n\n  if (!contact.name.trim() && !busy) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-serif text-lg text-charcoal\">{t.needDetails}</p>\n        <Link href={href(`/checkout?stream=${stream}`)} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.backToDetails}</Link>\n      </div>\n    );\n  }\n\n  function pay() {\n    if (!agree) {\n      setError(t.errTerms);\n      return;\n    }\n    setError('');\n    setBusy(true);\n    // DEMO: no money moves. The real payment gateway is connected here later.\n    window.setTimeout(() => {\n      const order = placeOrder(method, stream);\n      if (order) router.push(href('/order-confirmation'));\n      else setBusy(false);\n    }, 1800);\n  }\n\n  return (\n    <div className=\"grid items-start gap-8 lg:grid-cols-[1fr_360px]\">\n      <div className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose sm:p-8\">\n        <p className=\"rounded-md bg-saffron/15 px-4 py-2 text-sm font-semibold text-charcoal\">{t.demoNote}</p>\n\n        <fieldset className=\"mt-6\">\n          <legend className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.methodTitle}</legend>\n          <div className=\"mt-4 space-y-3\">\n            {t.methods.map((m) => (\n              <label key={m.key} className={`flex cursor-pointer items-start gap-3 rounded-xl border-2 p-4 transition-colors ${method === m.key ? 'border-saffron bg-rose/50' : 'border-rose hover:bg-rose/30'}`}>\n                <input type=\"radio\" name=\"method\" value={m.key} checked={method === m.key} onChange={() => setMethod(m.key)} className=\"mt-1 h-4 w-4 accent-maroon\" />\n                <span>\n                  <span className=\"block font-bold text-charcoal\">{m.label}</span>\n                  <span className=\"block text-sm text-charcoal/70\">{m.hint}</span>\n                </span>\n              </label>\n            ))}\n          </div>\n        </fieldset>\n\n        <p className=\"mt-4 text-sm text-charcoal/70\">{t.redirectNote}</p>\n\n        <div className=\"mt-6\">\n          <label className=\"flex cursor-pointer items-start gap-3\">\n            <input type=\"checkbox\" checked={agree} onChange={(e) => { setAgree(e.target.checked); if (e.target.checked) setError(''); }} aria-describedby={error ? 'terms-error' : undefined} className=\"mt-1 h-4 w-4 accent-maroon\" />\n            <span className=\"text-charcoal\">{t.termsText}</span>\n          </label>\n          {error && <p id=\"terms-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{error}</p>}\n        </div>\n\n        <div className=\"mt-8 flex flex-col-reverse gap-3 sm:flex-row sm:justify-between\">\n          <Link href={href(`/checkout?stream=${stream}`)} className=\"rounded-md border-2 border-maroon px-6 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backToDetails}</Link>\n          <button type=\"button\" onClick={pay} disabled={busy} className=\"rounded-md bg-maroon px-8 py-3 font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron disabled:cursor-wait disabled:opacity-70\">\n            {busy ? t.processing : t.payCta.replace('{amount}', rupees(total))}\n          </button>\n        </div>\n      </div>\n\n      <div className=\"lg:sticky lg:top-24\">\n        <OrderSummary stream={stream} lines={lines} total={total} locale={locale} t={t} />\n      </div>\n    </div>\n  );\n}\n","src/components/cart/ConfirmationView.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees } from '@/lib/format';\nimport { itemInfo, streamOf } from '@/lib/cartItem';\nimport { GOTRAMS, NAKSHATRAMS, RASIS, RELATIONS, labelFor } from '@/data/sankalpam';\nimport { useCart } from './CartProvider';\n\nexport default function ConfirmationView({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const { ready, order } = useCart();\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (!order) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-serif text-lg text-charcoal\">{t.noOrder}</p>\n        <Link href={href('/sevas')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.browse}</Link>\n      </div>\n    );\n  }\n\n  const stream = streamOf(order);\n  const isDonation = stream === 'donation';\n  const method = t.methods.find((m) => m.key === order.method)?.label ?? order.method;\n  const placed = order.placedAt.slice(0, 10);\n\n  return (\n    <div className=\"mx-auto max-w-3xl\">\n      <div className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-saffron sm:p-10\">\n        <div className=\"text-center\">\n          <span aria-hidden=\"true\" className=\"mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-saffron text-3xl font-bold text-charcoal\">✓</span>\n          <h2 className=\"mt-4 font-display text-4xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-3xl\">{isDonation ? t.confirmTitleDonation : t.confirmTitle}</h2>\n          <p className=\"mx-auto mt-2 max-w-xl font-serif text-lg text-charcoal/90\">{isDonation ? t.confirmTextDonation : t.confirmText}</p>\n          <p className=\"mt-2 text-sm font-semibold text-charcoal/70\">{t.receiptSent.replace('{email}', order.contact.email)}</p>\n        </div>\n\n        <dl className=\"mt-8 grid gap-4 rounded-xl bg-rose/50 p-5 sm:grid-cols-3\">\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.orderId}</dt><dd className=\"mt-1 font-bold text-charcoal\">{order.id}</dd></div>\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.orderDate}</dt><dd className=\"mt-1 font-bold text-charcoal\">{formatDate(placed, locale)}</dd></div>\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.paidWith}</dt><dd className=\"mt-1 font-bold text-charcoal\">{method}</dd></div>\n        </dl>\n\n        <h3 className=\"mt-8 font-display text-2xl font-semibold text-maroon\">{isDonation ? t.yourDonations : t.yourSevas}</h3>\n        <ul className=\"mt-2 divide-y divide-rose\">\n          {order.lines.map((l) => {\n            const info = itemInfo(stream, l.slug, locale);\n            return (\n              <li key={l.id} className=\"flex items-start justify-between gap-4 py-3\">\n                <div>\n                  <p className=\"font-semibold text-charcoal\">{info.name}</p>\n                  <p className=\"text-sm text-charcoal/70\">{l.date ? `${formatDate(l.date, locale)} · ` : ''}{l.devotee}{l.gotram ? ` · ${labelFor(GOTRAMS, l.gotram, locale)}` : ''}{l.rasi ? ` · ${labelFor(RASIS, l.rasi, locale)}` : ''}{l.nakshatram ? ` · ${labelFor(NAKSHATRAMS, l.nakshatram, locale)}` : ''}</p>\n                  {l.family && l.family.length > 0 && (\n                    <p className=\"text-sm text-charcoal/70\">{t.familyLabel}: {l.family.map((m) => (m.relation ? `${m.name} (${labelFor(RELATIONS, m.relation, locale)})` : m.name)).join(', ')}</p>\n                  )}\n                  <p className=\"text-sm text-charcoal/70\">{l.qty} × {rupees(l.unit)}</p>\n                </div>\n                <p className=\"shrink-0 font-bold\">{rupees(l.qty * l.unit)}</p>\n              </li>\n            );\n          })}\n        </ul>\n        <p className=\"mt-2 flex items-baseline justify-between border-t-2 border-rose pt-4\">\n          <span className=\"font-bold\">{t.total}</span>\n          <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(order.total)}</span>\n        </p>\n\n        <div className=\"mt-8 flex flex-col gap-3 sm:flex-row sm:justify-center\">\n          <Link href={href(isDonation ? '/donate' : '/sevas')} className=\"rounded-md bg-maroon px-7 py-3 text-center font-semibold text-white hover:bg-charcoal\">{isDonation ? t.moreDonations : t.moreSevas}</Link>\n          <Link href={href('/cart')} className=\"rounded-md border-2 border-maroon px-7 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backToCart}</Link>\n          <Link href={href('')} className=\"rounded-md border-2 border-maroon px-7 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backHome}</Link>\n        </div>\n      </div>\n    </div>\n  );\n}\n","src/app/[locale]/cart/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport CartView from '@/components/cart/CartView';\nimport ShopHero from '@/components/cart/ShopHero';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.shop.cartTitle} | ${t.site.name}`, robots: { index: false } };\n}\n\nexport default async function Page({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.shop;\n  return (\n    <main>\n      <ShopHero\n        title={t.cartTitle}\n        crumbLabel={t.crumbLabel}\n        crumbs={[{ label: dict.nav.home, href: `/${locale}` }, { label: t.cartTitle }]}\n        steps={t.steps}\n        current={0}\n      />\n      <section className=\"bg-white pb-16 pt-4 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <CartView t={t} locale={locale} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/checkout/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport CheckoutForm from '@/components/cart/CheckoutForm';\nimport ShopHero from '@/components/cart/ShopHero';\nimport { getDictionary } from '@/lib/dictionary';\nimport { parseStream } from '@/lib/cartItem';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }>; searchParams: Promise<{ stream?: string | string[] }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.shop.checkoutTitle} | ${t.site.name}`, robots: { index: false } };\n}\n\nexport default async function Page({ params, searchParams }: Params) {\n  const { locale } = await params;\n  const stream = parseStream((await searchParams).stream);\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.shop;\n  return (\n    <main>\n      <ShopHero\n        title={t.checkoutTitle}\n        crumbLabel={t.crumbLabel}\n        crumbs={[{ label: dict.nav.home, href: `/${locale}` }, { label: t.cartTitle, href: `/${locale}/cart` }, { label: t.checkoutTitle }]}\n        steps={t.steps}\n        current={1}\n      />\n      <section className=\"bg-white pb-16 pt-4 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <CheckoutForm t={t} locale={locale} stream={stream} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/payment/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport PaymentView from '@/components/cart/PaymentView';\nimport ShopHero from '@/components/cart/ShopHero';\nimport { getDictionary } from '@/lib/dictionary';\nimport { parseStream } from '@/lib/cartItem';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }>; searchParams: Promise<{ stream?: string | string[] }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.shop.paymentTitle} | ${t.site.name}`, robots: { index: false } };\n}\n\nexport default async function Page({ params, searchParams }: Params) {\n  const { locale } = await params;\n  const stream = parseStream((await searchParams).stream);\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.shop;\n  return (\n    <main>\n      <ShopHero\n        title={t.paymentTitle}\n        crumbLabel={t.crumbLabel}\n        crumbs={[{ label: dict.nav.home, href: `/${locale}` }, { label: t.cartTitle, href: `/${locale}/cart` }, { label: t.paymentTitle }]}\n        steps={t.steps}\n        current={2}\n      />\n      <section className=\"bg-white pb-16 pt-4 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <PaymentView t={t} locale={locale} stream={stream} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/order-confirmation/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport ConfirmationView from '@/components/cart/ConfirmationView';\nimport ShopHero from '@/components/cart/ShopHero';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.shop.confirmPageTitle} | ${t.site.name}`, robots: { index: false } };\n}\n\nexport default async function Page({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.shop;\n  return (\n    <main>\n      <ShopHero\n        title={t.confirmPageTitle}\n        crumbLabel={t.crumbLabel}\n        crumbs={[{ label: dict.nav.home, href: `/${locale}` }, { label: t.cartTitle, href: `/${locale}/cart` }, { label: t.confirmPageTitle }]}\n        steps={t.steps}\n        current={3}\n      />\n      <section className=\"bg-white pb-16 pt-4 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <ConfirmationView t={t} locale={locale} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/components/sevas/SankalpamWizard.tsx":"'use client';\n\nimport { useEffect, useId, useRef, useState } from 'react';\nimport Link from 'next/link';\nimport { useRouter } from 'next/navigation';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { WEEKDAYS, formatDate, rupees, todayISO, weekdayOf } from '@/lib/format';\nimport { dateMode, txt, type Seva } from '@/data/sevas';\nimport { GOTRAMS, MAX_FAMILY, NAKSHATRAMS, RASIS, RELATIONS, type FamilyMember } from '@/data/sankalpam';\nimport { useCart } from '@/components/cart/CartProvider';\nimport ChoiceField, { fieldClass } from './ChoiceField';\n\ntype T = Dictionary['sevas'];\ntype Member = FamilyMember & { uid: number };\n\nconst STORE = 'vedaneri.sankalpam.v1';\ntype Saved = { devotee: string; gotram: string; rasi: string; nakshatram: string; family: FamilyMember[] };\n\nfunction readSaved(): Saved | null {\n  try {\n    const raw = window.localStorage.getItem(STORE);\n    return raw ? (JSON.parse(raw) as Saved) : null;\n  } catch {\n    return null;\n  }\n}\nfunction writeSaved(v: Saved) {\n  try {\n    window.localStorage.setItem(STORE, JSON.stringify(v));\n  } catch {\n    /* ignore: storage can be blocked */\n  }\n}\n\n// Booking panel in three steps: 1 choose a seva, 2 sankalpam credentials, 3 date selection.\n// On the list page the seva comes from the card the visitor picked; on a detail page it is fixed.\nexport default function SankalpamWizard({\n  seva,\n  locale,\n  t,\n  fixed = false,\n  onChangeSeva,\n}: {\n  seva: Seva | null;\n  locale: Locale;\n  t: T;\n  fixed?: boolean;\n  onChangeSeva?: () => void;\n}) {\n  const router = useRouter();\n  const { add } = useCart();\n  const headingId = useId();\n  const headingRef = useRef<HTMLHeadingElement>(null);\n  const uid = useRef(0);\n  const firstRender = useRef(true);\n\n  const [step, setStep] = useState<1 | 2 | 3>(seva ? 2 : 1);\n  const [today, setToday] = useState('');\n  const [devotee, setDevotee] = useState('');\n  const [gotram, setGotram] = useState('');\n  const [rasi, setRasi] = useState('');\n  const [nakshatram, setNakshatram] = useState('');\n  const [family, setFamily] = useState<Member[]>([]);\n  const [date, setDate] = useState(seva && dateMode(seva) === 'fixed' ? seva.from ?? '' : '');\n  const [amountStr, setAmountStr] = useState('');\n  const [qty, setQty] = useState(1);\n  const [errors, setErrors] = useState<Record<string, string>>({});\n  const [added, setAdded] = useState<string | null>(null);\n\n  // After the page loads: today's date (kept out of the first render so server and browser match), and the details used last time\n  useEffect(() => {\n    setToday(todayISO());\n    const s = readSaved();\n    if (s) {\n      setDevotee(s.devotee ?? '');\n      setGotram(s.gotram ?? '');\n      setRasi(s.rasi ?? '');\n      setNakshatram(s.nakshatram ?? '');\n      setFamily((s.family ?? []).map((m) => ({ ...m, uid: ++uid.current })));\n    }\n  }, []);\n\n  // A different seva was picked: start again at step 2 with a clean date and amount\n  useEffect(() => {\n    setStep(seva ? 2 : 1);\n    setErrors({});\n    setAmountStr('');\n    setQty(1);\n    setDate(seva && dateMode(seva) === 'fixed' ? seva.from ?? '' : '');\n    if (seva) setAdded(null);\n  }, [seva]);\n\n  // Move keyboard and screen-reader focus to the panel heading when the step changes (not on first load)\n  useEffect(() => {\n    if (firstRender.current) {\n      firstRender.current = false;\n      return;\n    }\n    headingRef.current?.focus({ preventScroll: true });\n  }, [step, added, seva]);\n\n  const mode = seva ? dateMode(seva) : 'any';\n  const past = !!seva && (mode === 'fixed' || mode === 'range') && !!seva.to && !!today && seva.to < today;\n  const closed = !!seva && (seva.status !== 'open' || past);\n  const choose = !!seva && seva.amount === 0;\n  const unit = seva ? (choose ? Number(amountStr) || 0 : seva.amount) : 0;\n  const total = unit * (choose ? 1 : qty);\n  const dayName = seva && seva.weekday !== undefined ? WEEKDAYS[locale][seva.weekday] : '';\n  const minDate = mode === 'range' && seva?.from && seva.from > today ? seva.from : today;\n  const maxDate = mode === 'range' ? seva?.to : undefined;\n\n  const dateHelp = !seva\n    ? ''\n    : mode === 'fixed'\n      ? t.dateFixed.replace('{date}', formatDate(seva.from!, locale))\n      : mode === 'range'\n        ? t.dateRange.replace('{from}', formatDate(seva.from!, locale)).replace('{to}', formatDate(seva.to!, locale))\n        : mode === 'weekday'\n          ? t.dateWeekday.replaceAll('{day}', dayName)\n          : t.dateAny;\n\n  const clearError = (key: string) =>\n    setErrors((e) => {\n      if (!e[key]) return e;\n      const { [key]: _gone, ...rest } = e;\n      return rest;\n    });\n\n  const updateMember = (id: number, patch: Partial<FamilyMember>) => {\n    setFamily((f) => f.map((m) => (m.uid === id ? { ...m, ...patch } : m)));\n    if (patch.name) clearError(`m${id}`);\n  };\n\n  function goDate() {\n    const e: Record<string, string> = {};\n    if (!devotee.trim()) e.devotee = t.errName;\n    family.forEach((m) => {\n      if (!m.name.trim()) e[`m${m.uid}`] = t.errMember;\n    });\n    setErrors(e);\n    if (Object.keys(e).length === 0) setStep(3);\n  }\n\n  function validateDate() {\n    if (!seva) return false;\n    const e: Record<string, string> = {};\n    if (mode !== 'fixed') {\n      if (!date) e.date = t.errDate;\n      else if (date < today) e.date = t.errDatePast;\n      else if (mode === 'range' && (date < (seva.from as string) || date > (seva.to as string))) e.date = t.errDateRange;\n      else if (mode === 'weekday' && weekdayOf(date) !== seva.weekday) e.date = t.errDateWeekday.replace('{day}', dayName);\n    }\n    if (choose && !(Number(amountStr) >= seva.minAmount)) e.amount = t.errAmount.replace('{min}', rupees(seva.minAmount));\n    setErrors(e);\n    return Object.keys(e).length === 0;\n  }\n\n  function addToCart(goToCart: boolean) {\n    if (!seva || closed || !validateDate()) return;\n    const members: FamilyMember[] = family\n      .filter((m) => m.name.trim())\n      .map(({ name, relation, rasi: r, nakshatram: n }) => ({ name: name.trim(), relation, rasi: r, nakshatram: n }));\n    add({\n      slug: seva.slug,\n      qty: choose ? 1 : qty,\n      unit,\n      date,\n      devotee: devotee.trim(),\n      gotram,\n      nakshatram,\n      rasi,\n      family: members,\n    });\n    writeSaved({ devotee: devotee.trim(), gotram, rasi, nakshatram, family: members });\n    if (goToCart) {\n      router.push(`/${locale}/cart`);\n      return;\n    }\n    setAdded(txt(seva.name, locale));\n    onChangeSeva?.(); // on the list page this clears the picked seva so the panel returns to step 1\n  }\n\n  const stepLabels = [t.stepSeva, t.stepCredentials, t.stepDate];\n  const shownStep = added !== null ? 1 : step;\n  const title = shownStep === 1 ? t.panelTitleSeva : shownStep === 2 ? t.panelTitleCred : t.panelTitleDate;\n  const text = shownStep === 1 ? t.panelTextSeva : shownStep === 2 ? t.panelTextCred : t.panelTextDate;\n  const btnPrimary =\n    'rounded-md bg-maroon px-5 py-3 text-center font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron';\n  const btnGhost =\n    'rounded-md border-2 border-rose bg-white px-5 py-3 text-center font-semibold text-charcoal transition-colors hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron';\n\n  return (\n    <section aria-labelledby={headingId} className=\"rounded-2xl bg-white p-6 shadow-lg ring-1 ring-rose\">\n      <h2\n        id={headingId}\n        ref={headingRef}\n        tabIndex={-1}\n        className=\"font-display text-3xl font-semibold leading-tight text-maroon break-words focus:outline-none [html[lang='ta']_&]:!leading-[1.35] [html[lang='ta']_&]:text-xl\"\n      >\n        {title}\n      </h2>\n      <p className=\"mt-1 text-sm text-charcoal/70\">{text}</p>\n\n      {/* Steps */}\n      <ol aria-label={t.stepsLabel} className=\"mt-5 flex items-center gap-2\">\n        {stepLabels.map((label, i) => {\n          const n = i + 1;\n          const done = n < shownStep;\n          const on = n === shownStep;\n          return (\n            <li key={label} aria-current={on ? 'step' : undefined} className=\"flex items-center gap-2\">\n              <span\n                title={label}\n                className={`flex h-6 w-6 items-center justify-center rounded-full text-xs font-bold ${\n                  done || on ? 'bg-saffron text-charcoal' : 'bg-white text-charcoal/60 ring-1 ring-rose'\n                } ${on ? 'ring-2 ring-saffron/40 ring-offset-1' : ''}`}\n              >\n                {done ? '✓' : n}\n              </span>\n              <span className=\"sr-only\">{label}</span>\n              {i < stepLabels.length - 1 && <span aria-hidden=\"true\" className={`h-0.5 w-10 ${done ? 'bg-saffron' : 'bg-rose'}`} />}\n            </li>\n          );\n        })}\n      </ol>\n\n      {/* After adding */}\n      {added !== null && (\n        <div role=\"status\" className=\"mt-6 rounded-xl bg-saffron/15 p-5 text-center\">\n          <p className=\"font-display text-2xl font-semibold text-maroon\">✓ {t.added}</p>\n          <p className=\"mt-1 text-charcoal\">{added}</p>\n          <div className=\"mt-4 flex flex-col gap-3\">\n            <Link href={`/${locale}/cart`} className={btnPrimary}>{t.viewCart}</Link>\n            {fixed ? (\n              <Link href={`/${locale}/sevas`} className={btnGhost}>{t.keepBrowsing}</Link>\n            ) : (\n              <button type=\"button\" onClick={() => setAdded(null)} className={btnGhost}>{t.chooseAnother}</button>\n            )}\n          </div>\n        </div>\n      )}\n\n      {/* Step 1, nothing picked yet */}\n      {added === null && !seva && (\n        <p className=\"mt-6 rounded-xl bg-rose/50 p-5 text-center font-serif text-charcoal/85\">{t.panelEmpty}</p>\n      )}\n\n      {/* A seva is picked */}\n      {added === null && seva && (\n        <>\n          <div className=\"mt-5 flex items-start justify-between gap-3 rounded-lg bg-rose/50 p-3\">\n            <div className=\"min-w-0\">\n              <p className=\"font-semibold leading-snug text-charcoal\">{txt(seva.name, locale)}</p>\n              <p className=\"text-sm text-charcoal/75\">\n                {seva.amount > 0 ? rupees(seva.amount) : t.abilityLabel} · {txt(seva.when, locale)}\n              </p>\n            </div>\n            {!fixed && (\n              <button type=\"button\" onClick={onChangeSeva} className=\"shrink-0 text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal\">\n                {t.changeSeva}\n              </button>\n            )}\n          </div>\n\n          {closed ? (\n            <div className=\"mt-5 rounded-xl bg-rose/60 p-5 text-center\">\n              <p className=\"font-display text-2xl font-semibold text-maroon\">{past ? t.statusPast : t.statusClosed}</p>\n              <Link href={`/${locale}/sevas`} className=\"mt-4 inline-block rounded-md bg-maroon px-5 py-2.5 font-semibold text-white hover:bg-charcoal\">{t.backLabel}</Link>\n            </div>\n          ) : step === 2 ? (\n            <form\n              noValidate\n              onSubmit={(e) => {\n                e.preventDefault();\n                goDate();\n              }}\n              className=\"mt-5 space-y-4\"\n            >\n              <div>\n                <label htmlFor=\"kartha\" className=\"block text-sm font-bold text-charcoal\">{t.kartha}</label>\n                <input\n                  id=\"kartha\"\n                  value={devotee}\n                  onChange={(e) => {\n                    setDevotee(e.target.value);\n                    if (e.target.value.trim()) clearError('devotee');\n                  }}\n                  autoComplete=\"off\"\n                  aria-invalid={!!errors.devotee}\n                  aria-describedby={errors.devotee ? 'kartha-error' : 'kartha-hint'}\n                  className={`${fieldClass} mt-1`}\n                />\n                {errors.devotee ? (\n                  <p id=\"kartha-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors.devotee}</p>\n                ) : (\n                  <p id=\"kartha-hint\" className=\"mt-1 text-sm text-charcoal/70\">{t.devoteeNameHelp}</p>\n                )}\n              </div>\n\n              <ChoiceField id=\"gotram\" label={t.gotramFull} value={gotram} onChange={setGotram} options={GOTRAMS} locale={locale}\n                placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n              <div className={`grid gap-4 ${fixed ? 'sm:grid-cols-2' : ''}`}>\n                <ChoiceField id=\"rasi\" label={t.rasiFull} value={rasi} onChange={setRasi} options={RASIS} locale={locale}\n                  placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n                <ChoiceField id=\"nakshatram\" label={t.nakshatramFull} value={nakshatram} onChange={setNakshatram} options={NAKSHATRAMS} locale={locale}\n                  placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n              </div>\n              <p className=\"text-sm text-charcoal/70\">{t.optionalNote}</p>\n\n              {/* Family members */}\n              {family.map((m, i) => (\n                <fieldset key={m.uid} className=\"rounded-xl border border-rose p-4\">\n                  <legend className=\"px-1 text-sm font-bold text-maroon\">{t.familyTitle.replace('{n}', String(i + 1))}</legend>\n                  <div className=\"space-y-3\">\n                    <div>\n                      <label htmlFor={`m${m.uid}-name`} className=\"block text-sm font-bold text-charcoal\">{t.memberName}</label>\n                      <input\n                        id={`m${m.uid}-name`}\n                        value={m.name}\n                        onChange={(e) => updateMember(m.uid, { name: e.target.value })}\n                        autoComplete=\"off\"\n                        aria-invalid={!!errors[`m${m.uid}`]}\n                        aria-describedby={errors[`m${m.uid}`] ? `m${m.uid}-error` : undefined}\n                        className={`${fieldClass} mt-1`}\n                      />\n                      {errors[`m${m.uid}`] && <p id={`m${m.uid}-error`} role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors[`m${m.uid}`]}</p>}\n                    </div>\n                    <ChoiceField id={`m${m.uid}-relation`} label={t.relation} value={m.relation} onChange={(v) => updateMember(m.uid, { relation: v })} options={RELATIONS} locale={locale}\n                      placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n                    <div className={`grid gap-3 ${fixed ? 'sm:grid-cols-2' : ''}`}>\n                      <ChoiceField id={`m${m.uid}-rasi`} label={t.rasiFull} value={m.rasi} onChange={(v) => updateMember(m.uid, { rasi: v })} options={RASIS} locale={locale}\n                        placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n                      <ChoiceField id={`m${m.uid}-nakshatram`} label={t.nakshatramFull} value={m.nakshatram} onChange={(v) => updateMember(m.uid, { nakshatram: v })} options={NAKSHATRAMS} locale={locale}\n                        placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n                    </div>\n                    <button type=\"button\" onClick={() => setFamily((f) => f.filter((x) => x.uid !== m.uid))} className=\"text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal\">\n                      {t.removeMember}\n                    </button>\n                  </div>\n                </fieldset>\n              ))}\n\n              {family.length < MAX_FAMILY ? (\n                <button\n                  type=\"button\"\n                  onClick={() => setFamily((f) => [...f, { uid: ++uid.current, name: '', relation: '', rasi: '', nakshatram: '' }])}\n                  className=\"inline-flex items-center gap-2 text-sm font-bold text-maroon hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\"\n                >\n                  <span aria-hidden=\"true\" className=\"flex h-5 w-5 items-center justify-center rounded-full border-2 border-maroon text-sm leading-none\">+</span>\n                  {t.addFamily}\n                </button>\n              ) : (\n                <p className=\"text-sm text-charcoal/70\">{t.maxFamily.replace('{n}', String(MAX_FAMILY))}</p>\n              )}\n              {family.length > 0 && <p className=\"text-sm text-charcoal/70\">{t.familyHelp}</p>}\n\n              <div className={`grid gap-3 pt-2 ${fixed ? '' : 'sm:grid-cols-2'}`}>\n                {!fixed && (\n                  <button type=\"button\" onClick={onChangeSeva} className={btnGhost}>{t.back}</button>\n                )}\n                <button type=\"submit\" className={btnPrimary}>{t.nextDate}</button>\n              </div>\n            </form>\n          ) : (\n            <form\n              noValidate\n              onSubmit={(e) => {\n                e.preventDefault();\n                addToCart(false);\n              }}\n              className=\"mt-5 space-y-4\"\n            >\n              <div>\n                <label htmlFor=\"seva-date\" className=\"block text-sm font-bold text-charcoal\">{t.dateLabel}</label>\n                {mode === 'fixed' ? (\n                  <p id=\"seva-date\" className=\"mt-1 rounded-md bg-rose/50 px-4 py-2.5 font-semibold text-charcoal\">{formatDate(seva.from!, locale)}</p>\n                ) : (\n                  <input\n                    id=\"seva-date\"\n                    type=\"date\"\n                    value={date}\n                    min={minDate || undefined}\n                    max={maxDate}\n                    onChange={(e) => {\n                      setDate(e.target.value);\n                      clearError('date');\n                    }}\n                    aria-invalid={!!errors.date}\n                    aria-describedby={errors.date ? 'seva-date-error' : 'seva-date-hint'}\n                    className={`${fieldClass} mt-1`}\n                  />\n                )}\n                {errors.date ? (\n                  <p id=\"seva-date-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors.date}</p>\n                ) : (\n                  <p id=\"seva-date-hint\" className=\"mt-1 text-sm text-charcoal/70\">{dateHelp}</p>\n                )}\n              </div>\n              {seva.note && <p className=\"rounded-md bg-saffron/15 px-4 py-2 text-sm font-semibold text-charcoal\">{txt(seva.note, locale)}</p>}\n\n              {choose ? (\n                <div>\n                  <label htmlFor=\"amount\" className=\"block text-sm font-bold text-charcoal\">{t.amountInput}</label>\n                  <div className=\"relative mt-1\">\n                    <span aria-hidden=\"true\" className=\"absolute left-4 top-1/2 -translate-y-1/2 font-bold text-charcoal/70\">₹</span>\n                    <input\n                      id=\"amount\"\n                      inputMode=\"numeric\"\n                      value={amountStr}\n                      onChange={(e) => setAmountStr(e.target.value.replace(/\\D/g, ''))}\n                      aria-invalid={!!errors.amount}\n                      aria-describedby={errors.amount ? 'amount-error' : 'amount-hint'}\n                      className={`${fieldClass} pl-9`}\n                    />\n                  </div>\n                  {errors.amount ? (\n                    <p id=\"amount-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors.amount}</p>\n                  ) : (\n                    <p id=\"amount-hint\" className=\"mt-1 text-sm text-charcoal/70\">{t.amountHelp}</p>\n                  )}\n                </div>\n              ) : (\n                <div>\n                  <p className=\"text-sm font-bold text-charcoal\">{t.qtyLabel}</p>\n                  <div className=\"mt-1 inline-flex items-center rounded-md border-2 border-rose\">\n                    <button type=\"button\" aria-label={t.decrease} disabled={qty <= 1} onClick={() => setQty((q) => Math.max(1, q - 1))} className=\"h-11 w-11 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">−</button>\n                    <span aria-live=\"polite\" className=\"w-12 text-center text-lg font-bold\">{qty}</span>\n                    <button type=\"button\" aria-label={t.increase} disabled={qty >= seva.maxQty} onClick={() => setQty((q) => Math.min(seva.maxQty, q + 1))} className=\"h-11 w-11 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">+</button>\n                  </div>\n                </div>\n              )}\n\n              <p className=\"flex items-baseline justify-between border-t border-rose pt-4\">\n                <span className=\"font-semibold text-charcoal/80\">{t.totalLabel}</span>\n                <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</span>\n              </p>\n\n              <div className=\"grid gap-3\">\n                <button type=\"submit\" className={btnPrimary}>{t.addToSevaCart}</button>\n                <button type=\"button\" onClick={() => addToCart(true)} className={btnGhost}>{t.addAndGo}</button>\n                <button type=\"button\" onClick={() => setStep(2)} className=\"text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal\">{t.back}</button>\n              </div>\n            </form>\n          )}\n        </>\n      )}\n    </section>\n  );\n}\n"};
